import { copyFile, mkdir, readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";

import { CATALOG_SIZE, TICKET_TYPES } from "../app/ticket-catalog.ts";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const outputDirectory = path.join(root, "miniprogram", "shared");
const generatedHeader =
  "// AUTO-GENERATED by scripts/sync-miniprogram-core.mjs.\n" +
  "// Edit the files under app/ and run npm run sync:miniprogram instead.\n\n";

function toCommonJs(source, exportedNames) {
  let transformed = source
    .replace(/\bexport\s+function\s+/g, "function ")
    .replace(/\bexport\s+const\s+/g, "const ");
  transformed += `\nmodule.exports = { ${exportedNames.join(", ")} };\n`;
  return `${generatedHeader}${transformed}`;
}

const outputs = new Map([
  [
    path.join(outputDirectory, "ticket-engine.js"),
    toCommonJs(await readFile(path.join(root, "app", "ticket-engine.js"), "utf8"), [
      "evaluateVisiblePrize",
      "makeTicketOutcome",
      "TICKET_ENGINE_INTERNALS",
    ]),
  ],
  [
    path.join(outputDirectory, "prize-model.js"),
    toCommonJs(await readFile(path.join(root, "app", "prize-model.js"), "utf8"), [
      "makeBookPrizePool",
      "makeSeededRandom",
      "BOOK_PROFILES",
      "PRIZE_MODEL_INTERNALS",
    ]),
  ],
  [
    path.join(outputDirectory, "meeting-prize.js"),
    toCommonJs(await readFile(path.join(root, "app", "meeting-prize.js"), "utf8"), [
      "MEETING_WIN_SYMBOL",
      "MEETING_DOUBLE_SYMBOL",
      "calculateMeetingPrize",
      "meetingDecoySymbols",
      "makeMeetingCells",
    ]),
  ],
  [
    path.join(outputDirectory, "ticket-catalog.js"),
    `${generatedHeader}const TICKET_TYPES = ${JSON.stringify(TICKET_TYPES, null, 2)};\n` +
      `const CATALOG_SIZE = ${CATALOG_SIZE};\n\n` +
      "module.exports = { TICKET_TYPES, CATALOG_SIZE };\n",
  ],
]);

const checkOnly = process.argv.includes("--check");
let stale = false;

for (const [filePath, expected] of outputs) {
  let current = "";
  try {
    current = await readFile(filePath, "utf8");
  } catch {
    // Missing generated files are reported as stale in check mode.
  }
  if (current === expected) continue;
  stale = true;
  if (!checkOnly) {
    await mkdir(path.dirname(filePath), { recursive: true });
    await writeFile(filePath, expected, "utf8");
  }
}

const sourceSprite = path.join(root, "public", "assets", "ticket-symbols-v1.png");
const targetSprite = path.join(root, "miniprogram", "assets", "ticket-symbols-v1.png");
let spriteMatches = false;
try {
  const [source, target] = await Promise.all([readFile(sourceSprite), readFile(targetSprite)]);
  spriteMatches = source.equals(target);
} catch {
  // The asset will be copied below or reported as stale.
}
if (!spriteMatches) {
  stale = true;
  if (!checkOnly) {
    await mkdir(path.dirname(targetSprite), { recursive: true });
    await copyFile(sourceSprite, targetSprite);
  }
}

if (checkOnly && stale) {
  console.error("WeChat Mini Program shared files are stale. Run: npm run sync:miniprogram");
  process.exitCode = 1;
} else if (!checkOnly) {
  console.log(`Synced ${outputs.size} shared modules and the ticket pictogram sprite.`);
}
